from __future__ import annotations

import json
import sqlite3
from dataclasses import dataclass
from pathlib import Path
from typing import Any

from .models import Journal


@dataclass
class TransferBundle:
    version: int
    entries: list[Journal]


class Backend:
    def load(self) -> list[Journal]:
        raise NotImplementedError

    def save(self, entries: list[Journal]) -> None:
        raise NotImplementedError


class JsonBackend(Backend):
    def __init__(self, path: Path) -> None:
        self.path = path

    def load(self) -> list[Journal]:
        if not self.path.exists():
            return []
        with self.path.open("r", encoding="utf-8") as handle:
            raw = json.load(handle)
        return [Journal.from_backend_dict(item) for item in raw]

    def save(self, entries: list[Journal]) -> None:
        self.path.parent.mkdir(parents=True, exist_ok=True)
        payload = [entry.to_backend_dict() for entry in entries]
        with self.path.open("w", encoding="utf-8") as handle:
            json.dump(payload, handle, separators=(",", ":"))


class SQLiteBackend(Backend):
    def __init__(self, path: Path) -> None:
        self.path = path

    def _connect(self) -> sqlite3.Connection:
        self.path.parent.mkdir(parents=True, exist_ok=True)
        connection = sqlite3.connect(self.path)
        connection.execute(
            """
            CREATE TABLE IF NOT EXISTS journals (
                id INTEGER PRIMARY KEY,
                date TEXT NOT NULL,
                title TEXT NOT NULL,
                content TEXT NOT NULL,
                tags TEXT NOT NULL,
                priority INTEGER NULL
            )
            """
        )
        return connection

    def load(self) -> list[Journal]:
        if not self.path.exists():
            return []
        with self._connect() as connection:
            rows = connection.execute(
                "SELECT id, date, title, content, tags, priority FROM journals ORDER BY id ASC"
            ).fetchall()
        entries: list[Journal] = []
        for row in rows:
            tags = json.loads(row[4])
            entries.append(
                Journal.from_backend_dict(
                    {
                        "id": row[0],
                        "date": row[1],
                        "title": row[2],
                        "content": row[3],
                        "tags": tags,
                        "priority": row[5],
                    }
                )
            )
        return entries

    def save(self, entries: list[Journal]) -> None:
        with self._connect() as connection:
            connection.execute("DELETE FROM journals")
            connection.executemany(
                "INSERT INTO journals (id, date, title, content, tags, priority) VALUES (?, ?, ?, ?, ?, ?)",
                [
                    (
                        entry.id,
                        entry.iso_datetime,
                        entry.title,
                        entry.content,
                        json.dumps(entry.tags, separators=(",", ":")),
                        entry.priority,
                    )
                    for entry in entries
                ],
            )
            connection.commit()


def make_backend(backend_type: str, json_path: Path, sqlite_path: Path) -> Backend:
    if backend_type == "Json":
        return JsonBackend(json_path)
    return SQLiteBackend(sqlite_path)


def next_id(entries: list[Journal]) -> int:
    if not entries:
        return 0
    return max(entry.id for entry in entries) + 1


def sort_entries(entries: list[Journal]) -> list[Journal]:
    return sorted(entries, key=lambda entry: (entry.date, entry.priority if entry.priority is not None else -1, entry.id), reverse=True)


def dump_transfer(entries: list[Journal]) -> str:
    payload: dict[str, Any] = {
        "version": 100,
        "entries": [entry.to_transfer_dict() for entry in entries],
    }
    return json.dumps(payload, indent=2) + "\n"


def load_transfer(path: Path, starting_id: int) -> TransferBundle:
    with path.open("r", encoding="utf-8") as handle:
        raw = json.load(handle)
    if not isinstance(raw, dict):
        raise ValueError("invalid transfer file")
    version = int(raw["version"])
    raw_entries = raw["entries"]
    if not isinstance(raw_entries, list):
        raise ValueError("invalid transfer file")
    entries: list[Journal] = []
    next_entry_id = starting_id
    for item in raw_entries:
        if not isinstance(item, dict):
            raise ValueError("invalid transfer file")
        entries.append(Journal.from_transfer_dict(next_entry_id, item))
        next_entry_id += 1
    return TransferBundle(version=version, entries=entries)

