from __future__ import annotations

from dataclasses import dataclass, field
from datetime import date
from typing import Any


@dataclass
class Journal:
    id: int
    date: date
    title: str
    content: str = ""
    tags: list[str] = field(default_factory=list)
    priority: int | None = None

    @classmethod
    def from_backend_dict(cls, raw: dict[str, Any]) -> "Journal":
        return cls(
            id=int(raw["id"]),
            date=date.fromisoformat(str(raw["date"]).split("T", 1)[0]),
            title=str(raw["title"]),
            content=str(raw.get("content", "")),
            tags=[str(tag) for tag in raw.get("tags", [])],
            priority=None if raw.get("priority") is None else int(raw["priority"]),
        )

    @classmethod
    def from_transfer_dict(cls, new_id: int, raw: dict[str, Any]) -> "Journal":
        return cls(
            id=new_id,
            date=date.fromisoformat(str(raw["date"]).split("T", 1)[0]),
            title=str(raw["title"]),
            content=str(raw.get("content", "")),
            tags=[str(tag) for tag in raw.get("tags", [])],
            priority=None if raw.get("priority") is None else int(raw["priority"]),
        )

    def to_backend_dict(self) -> dict[str, Any]:
        return {
            "id": self.id,
            "date": self.iso_datetime,
            "title": self.title,
            "content": self.content,
            "tags": self.tags,
            "priority": self.priority,
        }

    def to_transfer_dict(self) -> dict[str, Any]:
        return {
            "date": self.iso_datetime,
            "title": self.title,
            "content": self.content,
            "tags": self.tags,
            "priority": self.priority,
        }

    @property
    def iso_datetime(self) -> str:
        return f"{self.date.isoformat()}T00:00:00Z"

    @property
    def display_date(self) -> str:
        return f"{self.date.day},{self.date.month},{self.date.year}"

