from __future__ import annotations

from dataclasses import dataclass
from pathlib import Path
from typing import Any

import tomli


class ConfigError(Exception):
    pass


@dataclass
class Config:
    backend_type: str
    scroll_per_page: int
    sync_os_clipboard: bool
    history_limit: int
    colored_tags: bool
    datum_visibility: str
    app_state_dir: Path
    export_show_confirmation: bool
    external_editor_auto_save: bool
    external_editor_temp_file_extension: str
    json_backend_file_path: Path
    sqlite_backend_file_path: Path


def default_paths(home: Path) -> dict[str, Path]:
    return {
        "config_dir": home / ".config" / "tui-journal",
        "state_dir": home / ".local" / "state" / "tui-journal",
        "cache_dir": home / ".cache" / "tui-journal",
        "log_path": home / ".cache" / "tui-journal" / "tui-journal.log",
        "json_path": home / "tui-journal" / "entries.json",
        "sqlite_path": home / "tui-journal" / "entries.db",
    }


def default_config(home: Path) -> Config:
    paths = default_paths(home)
    return Config(
        backend_type="Sqlite",
        scroll_per_page=5,
        sync_os_clipboard=False,
        history_limit=10,
        colored_tags=True,
        datum_visibility="show",
        app_state_dir=paths["state_dir"],
        export_show_confirmation=True,
        external_editor_auto_save=False,
        external_editor_temp_file_extension="txt",
        json_backend_file_path=paths["json_path"],
        sqlite_backend_file_path=paths["sqlite_path"],
    )


def render_config(config: Config) -> str:
    return (
        f'backend_type = "{config.backend_type}"\n'
        f"scroll_per_page = {config.scroll_per_page}\n"
        f"sync_os_clipboard = {str(config.sync_os_clipboard).lower()}\n"
        f"history_limit = {config.history_limit}\n"
        f"colored_tags = {str(config.colored_tags).lower()}\n"
        f'datum_visibility = "{config.datum_visibility}"\n'
        f'app_state_dir = "{config.app_state_dir}"\n\n'
        "[export]\n"
        f"show_confirmation = {str(config.export_show_confirmation).lower()}\n\n"
        "[external_editor]\n"
        f"auto_save = {str(config.external_editor_auto_save).lower()}\n"
        f'temp_file_extension = "{config.external_editor_temp_file_extension}"\n\n'
        "[json_backend]\n"
        f'file_path = "{config.json_backend_file_path}"\n\n'
        "[sqlite_backend]\n"
        f'file_path = "{config.sqlite_backend_file_path}"\n'
    )


def _validate_backend_type(value: Any) -> str:
    if value not in {"Json", "Sqlite"}:
        raise ConfigError(f"unknown variant `{value}`, expected `Json` or `Sqlite`")
    return str(value)


def _get_bool(table: dict[str, Any], key: str, fallback: bool) -> bool:
    value = table.get(key, fallback)
    return bool(value)


def _get_int(table: dict[str, Any], key: str, fallback: int) -> int:
    value = table.get(key, fallback)
    return int(value)


def _get_str(table: dict[str, Any], key: str, fallback: str) -> str:
    value = table.get(key, fallback)
    return str(value)


def resolve_config_input(custom_path: str | None, home: Path) -> tuple[Path, Path]:
    config_dir = default_paths(home)["config_dir"]
    if custom_path is None:
        return config_dir, config_dir / "config.toml"
    provided = Path(custom_path)
    if not provided.exists():
        raise ConfigError(f"Provided custom directory doesn't exit. Path: {provided}")
    if provided.is_dir():
        return provided, provided / "config.toml"
    return provided.parent, provided


def load_config(custom_path: str | None, home: Path) -> tuple[Config, Path]:
    config = default_config(home)
    config_dir, config_file = resolve_config_input(custom_path, home)
    if config_file.exists():
        try:
            with config_file.open("rb") as handle:
                data = tomli.load(handle)
        except tomli.TOMLDecodeError as exc:
            raise ConfigError(f"Failed to read configuration file. Error infos: {exc}") from exc

        try:
            if "backend_type" in data:
                config.backend_type = _validate_backend_type(data["backend_type"])
            if "scroll_per_page" in data:
                config.scroll_per_page = _get_int(data, "scroll_per_page", config.scroll_per_page)
            if "sync_os_clipboard" in data:
                config.sync_os_clipboard = _get_bool(data, "sync_os_clipboard", config.sync_os_clipboard)
            if "history_limit" in data:
                config.history_limit = _get_int(data, "history_limit", config.history_limit)
            if "colored_tags" in data:
                config.colored_tags = _get_bool(data, "colored_tags", config.colored_tags)
            if "datum_visibility" in data:
                config.datum_visibility = _get_str(data, "datum_visibility", config.datum_visibility)
            if "app_state_dir" in data:
                config.app_state_dir = Path(str(data["app_state_dir"]))

            export = data.get("export", {})
            if isinstance(export, dict) and "show_confirmation" in export:
                config.export_show_confirmation = _get_bool(export, "show_confirmation", config.export_show_confirmation)

            external_editor = data.get("external_editor", {})
            if isinstance(external_editor, dict):
                if "auto_save" in external_editor:
                    config.external_editor_auto_save = _get_bool(external_editor, "auto_save", config.external_editor_auto_save)
                if "temp_file_extension" in external_editor:
                    config.external_editor_temp_file_extension = _get_str(
                        external_editor,
                        "temp_file_extension",
                        config.external_editor_temp_file_extension,
                    )

            json_backend = data.get("json_backend", {})
            if isinstance(json_backend, dict) and "file_path" in json_backend:
                config.json_backend_file_path = Path(str(json_backend["file_path"]))

            sqlite_backend = data.get("sqlite_backend", {})
            if isinstance(sqlite_backend, dict) and "file_path" in sqlite_backend:
                config.sqlite_backend_file_path = Path(str(sqlite_backend["file_path"]))
        except (TypeError, ValueError, ConfigError) as exc:
            if isinstance(exc, ConfigError):
                raise ConfigError(f"Failed to read configuration file. Error infos: {exc}") from exc
            raise ConfigError(f"Failed to read configuration file. Error infos: {exc}") from exc
    return config, config_dir


def apply_cli_overrides(
    config: Config,
    *,
    json_file_path: str | None,
    sqlite_file_path: str | None,
    backend_type: str | None,
) -> Config:
    if json_file_path is not None:
        config.json_backend_file_path = Path(json_file_path)
        if backend_type is None:
            config.backend_type = "Json"
    if sqlite_file_path is not None:
        config.sqlite_backend_file_path = Path(sqlite_file_path)
        if backend_type is None:
            config.backend_type = "Sqlite"
    if backend_type is not None:
        config.backend_type = "Json" if backend_type == "json" else "Sqlite"
    return config


def resolve_theme_path(custom_path: str | None, home: Path) -> tuple[Path, str | None]:
    default_dir = default_paths(home)["config_dir"]
    if custom_path is None:
        return default_dir / "themes.toml", None
    provided = Path(custom_path)
    if not provided.exists():
        raise ConfigError(f"Provided custom directory doesn't exit. Path: {provided}")
    if provided.is_dir():
        return provided / "themes.toml", None
    return default_dir / "themes.toml", "INFO: Custom config directory is ignored in themese because it's not a directory."

