from __future__ import annotations

import sys
from dataclasses import dataclass
from pathlib import Path
from typing import Sequence

from .backend import load_transfer, make_backend
from .config import ConfigError, apply_cli_overrides, default_paths, load_config, render_config, resolve_theme_path
from .constants import (
    DEFAULT_THEME,
    VERSION,
    assign_help,
    import_help,
    print_config_help,
    theme_help,
    theme_subcommand_help,
    top_help,
)
from .tui import JournalApp, run_tui


@dataclass
class GlobalOptions:
    json_file_path: str | None = None
    sqlite_file_path: str | None = None
    backend_type: str | None = None
    config_path: str | None = None
    verbose: int = 0
    log_path: str | None = None
    command: str | None = None
    command_args: list[str] | None = None


def print_text(text: str, *, stream: str = "stdout") -> None:
    handle = sys.stdout if stream == "stdout" else sys.stderr
    handle.write(text)
    if not text.endswith("\n"):
        handle.write("\n")


def fail(text: str, code: int = 1, *, stream: str = "stderr") -> int:
    print_text(text, stream=stream)
    return code


def parse_global(argv: Sequence[str], prog: str, home: Path) -> tuple[GlobalOptions | None, int]:
    options = GlobalOptions(command_args=[])
    index = 0
    while index < len(argv):
        arg = argv[index]
        if arg in {"-h", "--help"}:
            print_text(top_help(prog, default_paths(home)["config_dir"], default_paths(home)["log_path"]))
            return None, 0
        if arg in {"-V", "--version"}:
            print_text(VERSION)
            return None, 0
        if arg in {"print-config", "pc", "import-journals", "imj", "assign-priority", "ap", "theme", "style", "help"}:
            options.command = arg
            options.command_args = list(argv[index + 1 :])
            return options, -1
        if arg in {"-j", "--json-file-path"}:
            if index + 1 >= len(argv):
                return None, fail(
                    "error: a value is required for '--json-file-path <FILE PATH>' but none was supplied\n\nFor more information, try '--help'.",
                    2,
                )
            options.json_file_path = argv[index + 1]
            index += 2
            continue
        if arg in {"-s", "--sqlite-file-path"}:
            if index + 1 >= len(argv):
                return None, fail(
                    "error: a value is required for '--sqlite-file-path <FILE PATH>' but none was supplied\n\nFor more information, try '--help'.",
                    2,
                )
            options.sqlite_file_path = argv[index + 1]
            index += 2
            continue
        if arg in {"-b", "--backend-type"}:
            if index + 1 >= len(argv):
                return None, fail(
                    "error: a value is required for '--backend-type <BACKEND_TYPE>' but none was supplied\n\nFor more information, try '--help'.",
                    2,
                )
            value = argv[index + 1]
            if value not in {"json", "sqlite"}:
                return None, fail(
                    f"error: invalid value '{value}' for '--backend-type <BACKEND_TYPE>'\n"
                    "  [possible values: json, sqlite]\n\n"
                    "For more information, try '--help'.",
                    2,
                )
            options.backend_type = value
            index += 2
            continue
        if arg in {"-c", "--config"}:
            if index + 1 >= len(argv):
                return None, fail(
                    "error: a value is required for '--config <DIR PATH>' but none was supplied\n\nFor more information, try '--help'.",
                    2,
                )
            options.config_path = argv[index + 1]
            index += 2
            continue
        if arg in {"-l", "--log"}:
            if index + 1 >= len(argv):
                return None, fail(
                    "error: a value is required for '--log <FILE PATH>' but none was supplied\n\nFor more information, try '--help'.",
                    2,
                )
            options.log_path = argv[index + 1]
            index += 2
            continue
        if arg == "-v":
            options.verbose = min(3, options.verbose + 1)
            index += 1
            continue
        if arg.startswith("-v") and len(arg) > 2 and set(arg[1:]) == {"v"}:
            options.verbose = min(3, options.verbose + len(arg) - 1)
            index += 1
            continue
        if arg.startswith("-"):
            return None, fail(
                f"error: unexpected argument '{arg}' found\n\nUsage: {prog} [OPTIONS] [COMMAND]\n\nFor more information, try '--help'.",
                2,
            )
        return None, fail(
            f"error: unrecognized subcommand '{arg}'\n\nUsage: {prog} [OPTIONS] [COMMAND]\n\nFor more information, try '--help'.",
            2,
        )
    return options, -1


def ensure_tty() -> bool:
    return sys.stdin.isatty() and sys.stdout.isatty()


def maybe_load_config(options: GlobalOptions, home: Path):
    try:
        config, _ = load_config(options.config_path, home)
    except ConfigError as exc:
        raise SystemExit(fail(f"Error: {exc}", 1))
    apply_cli_overrides(
        config,
        json_file_path=options.json_file_path,
        sqlite_file_path=options.sqlite_file_path,
        backend_type=options.backend_type,
    )
    return config


def handle_help(prog: str, options: GlobalOptions, home: Path) -> int:
    args = options.command_args or []
    if not args:
        print_text(top_help(prog, default_paths(home)["config_dir"], default_paths(home)["log_path"]))
        return 0
    topic = args[0]
    if topic in {"theme", "style"}:
        if len(args) > 1:
            print_text(theme_subcommand_help(prog, args[1]))
            return 0
        print_text(theme_help(prog))
        return 0
    if topic in {"print-config", "pc"}:
        print_text(print_config_help(prog))
        return 0
    if topic in {"import-journals", "imj"}:
        print_text(import_help(prog))
        return 0
    if topic in {"assign-priority", "ap"}:
        print_text(assign_help(prog))
        return 0
    return fail(
        f"error: unrecognized subcommand '{topic}'\n\nUsage: {prog} [OPTIONS] [COMMAND]\n\nFor more information, try '--help'.",
        2,
    )


def handle_theme(prog: str, options: GlobalOptions, home: Path) -> int:
    args = options.command_args or []
    if not args:
        print_text(theme_help(prog))
        return 2
    subcommand = args[0]
    if subcommand in {"-h", "--help", "help"}:
        if len(args) > 1:
            print_text(theme_subcommand_help(prog, args[1]))
            return 0
        print_text(theme_help(prog))
        return 0
    if len(args) > 1 and args[1] in {"-h", "--help"}:
        print_text(theme_subcommand_help(prog, subcommand))
        return 0
    try:
        theme_path, info = resolve_theme_path(options.config_path, home)
    except ConfigError as exc:
        return fail(f"Error: {exc}", 1)
    if info:
        print_text(info)
    if subcommand in {"print-path", "path"}:
        print_text(str(theme_path))
        return 0
    if subcommand in {"print-default", "default"}:
        print_text(DEFAULT_THEME, stream="stdout")
        return 0
    if subcommand in {"write-defaults", "write"}:
        if theme_path.exists():
            return fail(f"Error: Themes file already exists. Path: {theme_path}", 1)
        theme_path.parent.mkdir(parents=True, exist_ok=True)
        theme_path.write_text(DEFAULT_THEME, encoding="utf-8")
        print_text(f"Default themes have been written to {theme_path}")
        return 0
    return fail(
        f"error: unrecognized subcommand '{subcommand}'\n\nUsage: {prog} theme <COMMAND>\n\nFor more information, try '--help'.",
        2,
    )


def handle_print_config(prog: str, options: GlobalOptions, home: Path) -> int:
    args = options.command_args or []
    if args and args[0] in {"-h", "--help"}:
        print_text(print_config_help(prog))
        return 0
    config = maybe_load_config(options, home)
    print_text(render_config(config))
    return 0


def handle_assign_priority(prog: str, options: GlobalOptions, home: Path) -> int:
    args = options.command_args or []
    if args and args[0] in {"-h", "--help"}:
        print_text(assign_help(prog))
        return 0
    if not args:
        return fail(
            f"error: the following required arguments were not provided:\n  <PRIORITY>\n\nUsage: {prog} assign-priority <PRIORITY>\n\nFor more information, try '--help'.",
            2,
        )
    if args[0].startswith("-"):
        return fail(
            f"error: unexpected argument '{args[0]}' found\n\n  tip: to pass '{args[0]}' as a value, use '-- {args[0]}'\n\nUsage: {prog} assign-priority <PRIORITY>\n\nFor more information, try '--help'.",
            2,
        )
    if len(args) > 1:
        return fail(
            f"error: unexpected argument '{args[1]}' found\n\nUsage: {prog} assign-priority <PRIORITY>\n\nFor more information, try '--help'.",
            2,
        )
    if not ensure_tty():
        return fail("Error: No such device or address (os error 6)", 1)
    priority = int(args[0])
    config = maybe_load_config(options, home)
    backend = make_backend(config.backend_type, config.json_backend_file_path, config.sqlite_backend_file_path)
    entries = backend.load()
    for entry in entries:
        if entry.priority is None:
            entry.priority = priority
    backend.save(entries)
    app = JournalApp(
