    return run_tui(app)


def handle_import(prog: str, options: GlobalOptions, home: Path) -> int:
    args = options.command_args or []
    if args and args[0] in {"-h", "--help"}:
        print_text(import_help(prog))
        return 0

    import_path: str | None = None
    index = 0
    while index < len(args):
        arg = args[index]
        if arg in {"-p", "--path"}:
            if index + 1 >= len(args):
                return fail(
                    f"error: the following required arguments were not provided:\n  --path <FILE PATH>\n\nUsage: {prog} import-journals --path <FILE PATH>\n\nFor more information, try '--help'.",
                    2,
                )
            import_path = args[index + 1]
            index += 2
            continue
        return fail(
            f"error: unexpected argument '{arg}' found\n\nUsage: {prog} import-journals --path <FILE PATH>\n\nFor more information, try '--help'.",
            2,
        )
    if import_path is None:
        return fail(
            f"error: the following required arguments were not provided:\n  --path <FILE PATH>\n\nUsage: {prog} import-journals --path <FILE PATH>\n\nFor more information, try '--help'.",
            2,
        )
    if not ensure_tty():
        return fail("Error: No such device or address (os error 6)", 1)

    config = maybe_load_config(options, home)
    backend = make_backend(config.backend_type, config.json_backend_file_path, config.sqlite_backend_file_path)
    entries = backend.load()
    startup_error = None
    try:
        bundle = load_transfer(Path(import_path), 0 if not entries else max(entry.id for entry in entries) + 1)
    except Exception as exc:  # pragma: no cover - error text is intentionally coarse
        startup_error = f"Error while parsing import file.\nError: {exc}\n(O)k"
    else:
        entries.extend(bundle.entries)
        backend.save(entries)
    app = JournalApp(
        config=config,
        backend=backend,
        entries=entries,
        cwd=Path.cwd(),
        startup_banner="Importing journals...",
        startup_error=startup_error,
    )
    return run_tui(app)


def handle_default_tui(options: GlobalOptions, home: Path) -> int:
    if not ensure_tty():
        return fail("Error: No such device or address (os error 6)", 1)
    config = maybe_load_config(options, home)
    backend = make_backend(config.backend_type, config.json_backend_file_path, config.sqlite_backend_file_path)
    entries = backend.load()
    app = JournalApp(config=config, backend=backend, entries=entries, cwd=Path.cwd())
    return run_tui(app)


def main(argv: Sequence[str] | None = None) -> int:
    args = list(sys.argv[1:] if argv is None else argv)
    prog = Path(sys.argv[0]).name
    home = Path.home()

    parsed, status = parse_global(args, prog, home)
    if status != -1:
        return status
    assert parsed is not None

    command = parsed.command
    if command is None:
        return handle_default_tui(parsed, home)
    if command == "help":
        return handle_help(prog, parsed, home)
    if command in {"theme", "style"}:
        return handle_theme(prog, parsed, home)
    if command in {"print-config", "pc"}:
        return handle_print_config(prog, parsed, home)
    if command in {"assign-priority", "ap"}:
        return handle_assign_priority(prog, parsed, home)
    if command in {"import-journals", "imj"}:
        return handle_import(prog, parsed, home)
    return fail(
        f"error: unrecognized subcommand '{command}'\n\nUsage: {prog} [OPTIONS] [COMMAND]\n\nFor more information, try '--help'.",
        2,
    )


if __name__ == "__main__":
    raise SystemExit(main())

